#![no_main]
//! Feed arbitrary text to the authored behaviour-tree loader.
//!
//! Trees are authored by hand or generated by a tool, so the loader sees text written by
//! someone who was not thinking about the parser. The contract: any input is either a
//! usable tree or an error carrying a position, and never a panic.
use bevy_flock::behavior::tree::{BehaviorTree, NodeSpec};
use libfuzzer_sys::fuzz_target;

fuzz_target!(|data: &[u8]| {
    if let Ok(text) = std::str::from_utf8(data) {
        if let Ok(spec) = NodeSpec::from_ron(text) {
            // Compiling is where depth and arity limits are enforced, so a loader that
            // accepts a file it cannot compile must still report that as an error.
            let _ = BehaviorTree::try_from_spec(spec);
        }
    }
});
